// Category A compound picker — React Aria synchronizes color state; Sando owns the overlay look.
import {
  ColorPicker as AriaColorPicker,
  Button,
  DialogTrigger,
} from "react-aria-components";
import type { ColorPickerProps as AriaColorPickerProps } from "react-aria-components";
import type { ReactNode, Ref } from "react";
import { ColorSwatch } from "./ColorSwatch";
import { PopoverContent } from "./Popover";
import { roleSize, type ControlSize } from "./controlSize";
import "./ColorPicker.css";

export type ColorPickerSize = ControlSize;

export interface ColorPickerProps extends Omit<AriaColorPickerProps, "children"> {
  /**
   * Size axis for the trigger's height, inset, swatch and label type, so the trigger can share a
   * row with a field of the same size.
   *
   * @default "medium"
   */
  size?: ColorPickerSize;
  /** Disables the trigger, so the picker cannot be opened. Declared here rather than inherited:
   *  React Aria's ColorPicker is state-only (ValueBase + SlotProps) and carries no state props,
   *  while the trigger button this component owns does. */
  isDisabled?: boolean;
  /** Trigger label — required: it is the trigger button's visible + accessible name.
   *  No default is baked in (contract §7b: the .tsx ships no default content). */
  label: string;
  /** Dialog contents — required for the same reason as `label`: the picker controls are the
   *  consumer's composition, so the .tsx ships none (contract §7b). */
  children: ReactNode;
  /** Additional class. sd-color-picker is always preserved. */
  className?: string;
  /** Passed to the Sando root DOM node. */
  ref?: Ref<HTMLDivElement>;
}

export function ColorPicker({
  size = "medium",
  isDisabled,
  label,
  children,
  className,
  ref,
  ...props
}: ColorPickerProps) {
  return (
    <AriaColorPicker {...props}>
      <div ref={ref} className={className ? `sd-color-picker ${className}` : "sd-color-picker"}>
        <DialogTrigger>
          <Button
            className={`sd-color-picker__trigger sd-type-label-${roleSize(size)}`}
            data-size={size}
            isDisabled={isDisabled}
          >
            <ColorSwatch className="sd-color-picker__swatch" />
            <span className="sd-color-picker__label">{label}</span>
          </Button>
          <PopoverContent>
            <div className="sd-color-picker__panel">{children}</div>
          </PopoverContent>
        </DialogTrigger>
      </div>
    </AriaColorPicker>
  );
}

.sd-color-picker {
  display: inline-flex;
}

.sd-color-picker__trigger {
  --sd-color-picker-trigger-radius-current: var(--sd-color-picker-trigger-radius-medium);
  --sd-color-picker-trigger-height-current: var(--sd-color-picker-trigger-height-medium);
  --sd-color-picker-trigger-padding-inline-current: var(--sd-color-picker-trigger-padding-inline-medium);
  --sd-color-picker-swatch-size-current: var(--sd-color-picker-swatch-size-medium);
  display: inline-flex;
  align-items: center;
  gap: var(--sd-color-picker-trigger-gap);
  min-height: var(--sd-color-picker-trigger-height-current);
  padding-inline: var(--sd-color-picker-trigger-padding-inline-current);
  background: var(--sd-color-picker-trigger-background);
  color: var(--sd-color-picker-trigger-foreground);
  border: var(--sd-color-picker-trigger-border-width) solid var(--sd-color-picker-trigger-border);
  border-radius: var(--sd-color-picker-trigger-radius-current);
  corner-shape: superellipse(var(--sd-radius-curve));
  cursor: pointer;
  position: relative;
  transition:
    border-color var(--sd-duration-moderate) var(--sd-easing-standard),
    box-shadow var(--sd-duration-moderate) var(--sd-easing-standard);
  outline: none;
}

/* Interaction state-layer overlay for the pressed tint (hover = border, bordered-control pattern). */
.sd-color-picker__trigger::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  corner-shape: inherit;
  background: transparent;
  pointer-events: none;
  transition: background-color var(--sd-duration-moderate) var(--sd-easing-standard);
}
.sd-color-picker__trigger[data-hovered] {
  border-color: var(--sd-color-picker-trigger-border-hover);
}
.sd-color-picker__trigger[data-pressed]::after {
  background: var(--sd-state-pressed);
}
.sd-color-picker__trigger[data-focus-visible] {
  border-color: var(--sd-color-picker-trigger-border-focus);
  box-shadow: 0 0 0 var(--sd-state-focus-ring-width) color-mix(in srgb, var(--sd-state-focus-ring) calc(var(--sd-state-focus-ring-opacity) * 100%), transparent);
  outline: var(--sd-state-focus-ring-width) solid transparent;
}
.sd-color-picker__trigger[data-disabled] {
  opacity: var(--sd-state-disabled);
  cursor: not-allowed;
}

/* size → the trigger's height, inset and swatch move together; the swatch reads the relay the
   trigger sets, since it is the trigger's own child. */
.sd-color-picker__trigger[data-size="x-small"] {
  --sd-color-picker-trigger-radius-current: var(--sd-color-picker-trigger-radius-x-small);
  --sd-color-picker-trigger-height-current: var(--sd-color-picker-trigger-height-x-small);
  --sd-color-picker-trigger-padding-inline-current: var(--sd-color-picker-trigger-padding-inline-x-small);
  --sd-color-picker-swatch-size-current: var(--sd-color-picker-swatch-size-x-small);
}
.sd-color-picker__trigger[data-size="small"] {
  --sd-color-picker-trigger-radius-current: var(--sd-color-picker-trigger-radius-small);
  --sd-color-picker-trigger-height-current: var(--sd-color-picker-trigger-height-small);
  --sd-color-picker-trigger-padding-inline-current: var(--sd-color-picker-trigger-padding-inline-small);
  --sd-color-picker-swatch-size-current: var(--sd-color-picker-swatch-size-small);
}
.sd-color-picker__trigger[data-size="large"] {
  --sd-color-picker-trigger-radius-current: var(--sd-color-picker-trigger-radius-large);
  --sd-color-picker-trigger-height-current: var(--sd-color-picker-trigger-height-large);
  --sd-color-picker-trigger-padding-inline-current: var(--sd-color-picker-trigger-padding-inline-large);
  --sd-color-picker-swatch-size-current: var(--sd-color-picker-swatch-size-large);
}
.sd-color-picker__trigger[data-size="x-large"] {
  --sd-color-picker-trigger-radius-current: var(--sd-color-picker-trigger-radius-x-large);
  --sd-color-picker-trigger-height-current: var(--sd-color-picker-trigger-height-x-large);
  --sd-color-picker-trigger-padding-inline-current: var(--sd-color-picker-trigger-padding-inline-x-large);
  --sd-color-picker-swatch-size-current: var(--sd-color-picker-swatch-size-x-large);
}

.sd-color-picker__swatch {
  width: var(--sd-color-picker-swatch-size-current);
  height: var(--sd-color-picker-swatch-size-current);
  border-radius: var(--sd-color-picker-swatch-radius);
  corner-shape: superellipse(var(--sd-radius-curve));
}

.sd-color-picker__label {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.sd-color-picker__panel {
  display: grid;
  gap: var(--sd-color-picker-dialog-gap);
  outline: none;
}
